import { useState, useCallback } from "react";
import { Button } from "../../components/ui/button";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "../../components/ui/card";
import { Alert, AlertDescription } from "../../components/ui/alert";
import { AlertCircle, X } from "lucide-react";
import { ActionFormProvider } from "../../components/forms/action-forms/ActionFormContext";
import { TextField } from "../../components/forms/action-forms/fields/TextField";
import { SwitchField } from "../../components/forms/action-forms/fields/SwitchField";
import { SelectField } from "../../components/forms/action-forms/fields/SelectField";
import { RadioField } from "../../components/forms/action-forms/fields/RadioField";
import { TextareaField } from "../../components/forms/action-forms/fields/TextareaField";
import { CheckboxGroupField } from "../../components/forms/action-forms/fields/CheckboxGroupField";
import { CheckboxField } from "../../components/forms/action-forms/fields/CheckboxField";
import { useFormSubmit } from "./hooks";
import { formSchema } from "./formSchema";

export default function ConditionalForm() {
  const SUBMIT_EXCLUDED = new Set<string>();
  const { submit } = useFormSubmit();
  const [values, setValues] = useState<Record<string, unknown>>({
      "firstName": "",
      "lastName": "",
      "email": "",
      "isCompany": false,
      "companyName": "",
      "registrationNumber": "",
      "taxId": "",
      "companySize": "",
      "accountType": "",
      "billingEmail": "",
      "paymentMethod": "",
      "accountManager": "",
      "expectedUsers": "",
      "customRequirements": "",
      "services": [],
      "needsShipping": false,
      "street": "",
      "shippingCity": "",
      "shippingPostalCode": "",
      "shippingCountry": ""
  });
  const [errors, setErrors] = useState<Record<string, string[]>>({});
  const [globalError, setGlobalError] = useState<string | null>(null);
  const [isPending, setIsPending] = useState(false);

  const setValue = useCallback((name: string, value: unknown) => {
    setValues((prev) => ({ ...prev, [name]: value }));
    setErrors((prev) => { const next = { ...prev }; delete next[name]; return next; });
    if (globalError) setGlobalError(null);
  }, [globalError]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsPending(true);
    setGlobalError(null);

    const result = formSchema.safeParse(values);
    if (!result.success) {
      const flat = result.error.flatten().fieldErrors as Record<string, string[]>;
      setErrors(flat);
      setIsPending(false);
      return;
    }

    try {
      const payload = { ...(result.data as Record<string, unknown>) };
      for (const name of SUBMIT_EXCLUDED) {
        delete payload[name];
        const p = `${name}__`;
        for (const k of Object.keys(payload)) {
          if (k.startsWith(p)) delete payload[k];
        }
      }
      await submit(payload);
    } catch (error: any) {
      setGlobalError(error?.message || "An unexpected error occurred");
    } finally {
      setIsPending(false);
    }
  };

  return (
    <div className="container mx-auto py-8 max-w-3xl">
      <ActionFormProvider value={{ values, setValue, errors, isPending }}>
        <form onSubmit={handleSubmit} className="space-y-6">
          {globalError && (
            <Alert variant="destructive">
              <AlertCircle className="h-4 w-4" />
              <AlertDescription className="flex items-center justify-between">
                {globalError}
                <button type="button" onClick={() => setGlobalError(null)}><X className="h-4 w-4" /></button>
              </AlertDescription>
            </Alert>
          )}

            <Card>
              <CardHeader>
                <CardTitle>Basic Information</CardTitle>
              </CardHeader>
              <CardContent className="grid gap-4 md:grid-cols-2">
              <TextField config={{
                  "type": "text",
                  "name": "firstName",
                  "label": "First Name",
                  "placeholder": "John",
                  "required": true
                }} />
              <TextField config={{
                  "type": "text",
                  "name": "lastName",
                  "label": "Last Name",
                  "placeholder": "Doe",
                  "required": true
                }} />
              <TextField config={{
                  "type": "email",
                  "name": "email",
                  "label": "Email",
                  "placeholder": "john@example.com",
                  "required": true
                }} />
              <SwitchField config={{
                  "type": "switch",
                  "name": "isCompany",
                  "label": "Account Type",
                  "switchLabel": "Register as a company?"
                }} />
              </CardContent>
            </Card>

            <Card>
              <CardHeader>
                <CardTitle>Company Information</CardTitle>
                <CardDescription>Fill in your company details</CardDescription>
              </CardHeader>
              <CardContent className="grid gap-4 md:grid-cols-2">
              <TextField config={{
                  "type": "text",
                  "name": "companyName",
                  "label": "Company Name",
                  "placeholder": "Acme Inc.",
                  "required": true,
                  "condition": {
                    "field": "isCompany",
                    "operator": "isTrue"
                  }
                }} />
              <TextField config={{
                  "type": "text",
                  "name": "registrationNumber",
                  "label": "Registration Number",
                  "placeholder": "REG-123456",
                  "required": true,
                  "condition": {
                    "field": "isCompany",
                    "operator": "isTrue"
                  }
                }} />
              <TextField config={{
                  "type": "text",
                  "name": "taxId",
                  "label": "Tax ID",
                  "placeholder": "TAX-789012",
                  "condition": {
                    "field": "isCompany",
                    "operator": "isTrue"
                  }
                }} />
              <SelectField config={{
                  "type": "select",
                  "name": "companySize",
                  "label": "Company Size",
                  "condition": {
                    "field": "isCompany",
                    "operator": "isTrue"
                  },
                  "options": [
                    {
                      "label": "1-10 employees",
                      "value": "1-10"
                    },
                    {
                      "label": "11-50 employees",
                      "value": "11-50"
                    },
                    {
                      "label": "51-200 employees",
                      "value": "51-200"
                    },
                    {
                      "label": "200+ employees",
                      "value": "200+"
                    }
                  ]
                }} />
              </CardContent>
            </Card>

            <Card>
              <CardHeader>
                <CardTitle>Account & Services</CardTitle>
              </CardHeader>
              <CardContent className="grid gap-4">
              <RadioField config={{
                  "type": "radio",
                  "name": "accountType",
                  "label": "Account Type",
                  "options": [
                    {
                      "label": "Basic Account — Free tier with limited features",
                      "value": "basic"
                    },
                    {
                      "label": "Pro Account — Advanced features + priority support",
                      "value": "pro"
                    },
                    {
                      "label": "Enterprise — Custom solutions + dedicated manager",
                      "value": "enterprise"
                    }
                  ]
                }} />
              <TextField config={{
                  "type": "email",
                  "name": "billingEmail",
                  "label": "Billing Email",
                  "placeholder": "billing@company.com",
                  "condition": {
                    "field": "accountType",
                    "operator": "equals",
                    "value": "pro"
                  }
                }} />
              <SelectField config={{
                  "type": "select",
                  "name": "paymentMethod",
                  "label": "Preferred Payment Method",
                  "condition": {
                    "field": "accountType",
                    "operator": "equals",
                    "value": "pro"
                  },
                  "options": [
                    {
                      "label": "Credit/Debit Card",
                      "value": "card"
                    },
                    {
                      "label": "Bank Transfer",
                      "value": "bank"
                    },
                    {
                      "label": "PayPal",
                      "value": "paypal"
                    }
                  ]
                }} />
              <TextField config={{
                  "type": "text",
                  "name": "accountManager",
                  "label": "Dedicated Account Manager",
                  "placeholder": "Preferred contact name",
                  "condition": {
                    "field": "accountType",
                    "operator": "equals",
                    "value": "enterprise"
                  }
                }} />
              <TextField config={{
                  "type": "number",
                  "name": "expectedUsers",
                  "label": "Expected Monthly Users",
                  "placeholder": "1000",
                  "condition": {
                    "field": "accountType",
                    "operator": "equals",
                    "value": "enterprise"
                  }
                }} />
              <TextareaField config={{
                  "type": "textarea",
                  "name": "customRequirements",
                  "label": "Custom Requirements",
                  "placeholder": "Describe your specific needs...",
                  "rows": 3,
                  "condition": {
                    "field": "accountType",
                    "operator": "equals",
                    "value": "enterprise"
                  }
                }} />
              <CheckboxGroupField config={{
                  "type": "checkboxgroup",
                  "name": "services",
                  "label": "Additional Services",
                  "orientation": "horizontal",
                  "options": [
                    {
                      "label": "API Access",
                      "value": "api"
                    },
                    {
                      "label": "SSO Integration",
                      "value": "sso"
                    },
                    {
                      "label": "Advanced Analytics",
                      "value": "analytics"
                    },
                    {
                      "label": "24/7 Support",
                      "value": "support"
                    }
                  ]
                }} />
              <CheckboxField config={{
                  "type": "checkbox",
                  "name": "needsShipping",
                  "label": "Shipping",
                  "checkboxLabel": "I need physical products shipped to me"
                }} />
              </CardContent>
            </Card>

            <Card>
              <CardHeader>
                <CardTitle>Shipping Address</CardTitle>
              </CardHeader>
              <CardContent className="grid gap-4 md:grid-cols-2">
              <TextField config={{
                  "type": "text",
                  "name": "street",
                  "label": "Street Address",
                  "placeholder": "123 Main Street",
                  "condition": {
                    "field": "needsShipping",
                    "operator": "isTrue"
                  }
                }} />
              <TextField config={{
                  "type": "text",
                  "name": "shippingCity",
                  "label": "City",
                  "placeholder": "New York",
                  "condition": {
                    "field": "needsShipping",
                    "operator": "isTrue"
                  }
                }} />
              <TextField config={{
                  "type": "text",
                  "name": "shippingPostalCode",
                  "label": "Postal Code",
                  "placeholder": "10001",
                  "condition": {
                    "field": "needsShipping",
                    "operator": "isTrue"
                  }
                }} />
              <SelectField config={{
                  "type": "select",
                  "name": "shippingCountry",
                  "label": "Country",
                  "condition": {
                    "field": "needsShipping",
                    "operator": "isTrue"
                  },
                  "options": [
                    {
                      "label": "United States",
                      "value": "us"
                    },
                    {
                      "label": "United Kingdom",
                      "value": "uk"
                    },
                    {
                      "label": "Canada",
                      "value": "ca"
                    },
                    {
                      "label": "Australia",
                      "value": "au"
                    }
                  ]
                }} />
              </CardContent>
            </Card>

            <Button type="submit" disabled={isPending}>
              {isPending ? "Submitting..." : "Create Account"}
            </Button>
        </form>
      </ActionFormProvider>
    </div>
  );
}

import { z } from "zod";

const baseSchema = z.object({
  firstName: z.string().min(1, "First Name is required"),
  lastName: z.string().min(1, "Last Name is required"),
  email: z.email("Invalid email").min(1, "Email is required"),
  isCompany: z.boolean(),
  companyName: z.string().optional(),
  registrationNumber: z.string().optional(),
  taxId: z.string().optional(),
  companySize: z.string().optional(),
  accountType: z.string().optional(),
  billingEmail: z.preprocess((v) => (v === "" || v === null || v === undefined ? undefined : v), z.email("Invalid email").optional()),
  paymentMethod: z.string().optional(),
  accountManager: z.string().optional(),
  expectedUsers: z.coerce.number().optional(),
  customRequirements: z.string().optional(),
  services: z.array(z.string()).optional(),
  needsShipping: z.boolean(),
  street: z.string().optional(),
  shippingCity: z.string().optional(),
  shippingPostalCode: z.string().optional(),
  shippingCountry: z.string().optional(),
});

export const formSchema = baseSchema.superRefine((data, ctx) => {
  if (data.isCompany === true) {
    if (!data.companyName || (typeof data.companyName === "string" && data.companyName.length === 0)) {
      ctx.addIssue({ code: z.ZodIssueCode.custom, message: "Company Name is required", path: ["companyName"] });
    }
  }
  if (data.isCompany === true) {
    if (!data.registrationNumber || (typeof data.registrationNumber === "string" && data.registrationNumber.length === 0)) {
      ctx.addIssue({ code: z.ZodIssueCode.custom, message: "Registration Number is required", path: ["registrationNumber"] });
    }
  }
});

export type FormValues = z.infer<typeof formSchema>;

